fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn next(seed:&mut u64)->BigInt{let mut b=[0u8;32];for c in b.chunks_mut(8){*seed^=*seed<<13;*seed^=*seed>>7;*seed^=*seed<<17;c.copy_from_slice(&seed.to_le_bytes());}BigInt::from_bytes_le(Sign::Plus,&b)}
fn strvec(v:&[BigInt])->Vec<String>{v.iter().map(ToString::to_string).collect()}

struct Dense{moduli:[u64;5],product:BigInt,coefficients:[BigInt;5],estimates:[u64;5]}
fn greedy(p:&BigInt,factor:u32,previous:&BigInt)->[u64;5]{let mut values=Vec::new();let mut product=BigInt::one();let mut c=1u64;while product<factor*p{let m=(1u64<<52)-c;if gcd(m.into(),&product*previous).is_one(){values.push(m);product*=m;}c+=2;}values.try_into().unwrap()}
fn dense(moduli:[u64;5],premult:&BigInt)->Dense{let product=moduli.iter().fold(BigInt::one(),|a,m|a*m);let coefficients=std::array::from_fn(|i|{let c=&product/moduli[i];rem(premult*&c*inverse(&c,&moduli[i].into()),&product)});let estimates=std::array::from_fn(|i|(((&coefficients[i]<<64usize)+&product-1u32)/&product).to_u64().unwrap());Dense{moduli,product,coefficients,estimates}}
fn normalized_quotient(d:&Dense,x:&BigInt,y:&BigInt)->u64{let b=BigInt::one()<<52usize;let k:BigInt=(0..5).fold(BigInt::zero(),|a,i|{let s=rem(x*y*&b,&d.moduli[i].into());a+s*d.estimates[i]});(k>>64usize).to_u64().unwrap()}
fn dense_metadata(p:&BigInt)->(Value,Dense){let a=greedy(p,9,&BigInt::one());let ma=a.iter().fold(BigInt::one(),|s,m|s*m);let b=greedy(p,6,&ma);let mb=b.iter().fold(BigInt::one(),|s,m|s*m);let radix=BigInt::one()<<52usize;
 let pre1=rem(-inverse(p,&ma)*inverse(&radix,&ma),&ma);let pre2=rem(&ma*inverse(&radix,&mb),&mb);let x=dense(a,&pre1);let y=dense(b,&pre2);
 let bound=|d:&Dense|{let raw:BigInt=(0..5).fold(BigInt::zero(),|s,i|s+BigInt::from(d.moduli[i]-1)*d.estimates[i]);(raw>>64usize).to_u64().unwrap()};
 let kb=[bound(&x),bound(&y)];let meta=json!({"left_moduli":a,"right_moduli":b,"M":ma.to_string(),"N":mb.to_string(),"left_normalized_coefficients":strvec(&x.coefficients),"right_normalized_coefficients":strvec(&y.coefficients),"left_reciprocal_estimates":x.estimates,"right_reciprocal_estimates":y.estimates,"correction_quotient_box_upper_bounds":kb,"quotient_upper_bits":kb.map(|k|64-k.leading_zeros()),"single_integer_residue_lanes_IFMA_sites":40,"eight_instance_residue_planes_IFMA_sites":200,"ordinary_eight_instance_IFMA_sites":100,"logical_u64_constant_bytes":800,"padded_coefficient_vectors_bytes_excluding_object_metadata":1232,"limits":"Source-template count for inspected algorithm, not native code/cycles or all-RNS lower bound; quotient bounds cover canonical channel inputs"});(meta,x)
}
fn check(r:&mut Rns,x:&[BigInt;4],mode:u8,invp_m:&BigInt,minv:&BigInt)->(BigInt,State,bool){let states=x.each_ref().map(|v|r.state(v));let z=r.apply(&states[0],&states[1],&states[2],&states[3],mode);let integer=r.integer(&z);assert!(integer<4u32*&r.p);
 let mut t=&x[0]*&x[1];if mode==1{t+=&x[2]*&x[3];}if mode==2{t=t-&x[2]*&x[3]+64u32*&r.p*&r.p;}assert!(t>=BigInt::zero()&&t<128u32*&r.p*&r.p);
 let q=rem(-&t*invp_m,&r.left.product);let canonical=(&t+&r.p*q)/&r.left.product;let extra=integer!=canonical;assert!(integer==canonical||integer==&canonical+&r.p);
 assert_eq!(rem(&integer*minv,&r.p),rem(t*minv*minv,&r.p));(integer,z,extra)
}
